INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('claude-code','Claude Code','ai-coding','付费',1,NULL,'claude code 在终端里读代码、改文件、跑命令的 ai 编程搭子。 anthropic 推出的命令行编程智能体，能围绕整个代码库规划并执行多步任务，适合把重复改动、排查和验证流程交给代理完成。 终端智能体 代码库理解 cli anthropic 在现有仓库中跨文件实现一项功能 接手陌生项目时梳理结构与调用关系 把测试、修复和提交前检查串成一条流程','{"id":"claude-code","name":"Claude Code","tagline":"在终端里读代码、改文件、跑命令的 AI 编程搭子。","description":"Anthropic 推出的命令行编程智能体，能围绕整个代码库规划并执行多步任务，适合把重复改动、排查和验证流程交给代理完成。","categoryId":"ai-coding","website":"https://www.anthropic.com/claude-code","github":"https://github.com/anthropics/claude-code","install":"npm install -g @anthropic-ai/claude-code","tags":["终端智能体","代码库理解","CLI","Anthropic"],"platforms":["CLI"],"pricing":"付费","icon":"✳","accent":"#D97757","featured":true,"useCases":["在现有仓库中跨文件实现一项功能","接手陌生项目时梳理结构与调用关系","把测试、修复和提交前检查串成一条流程"],"highlights":["理解项目上下文后再动手，减少反复粘贴","工具能力覆盖读取、编辑与终端命令","改动可在终端中逐项审查和继续对话"],"logo":"/media/icons/claude-code.png"}',0) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('cursor','Cursor','ai-coding','免费增值',0,NULL,'cursor 把 ai 对话、补全与多文件编辑放进熟悉的编辑器。 围绕 ai 工作流打造的代码编辑器，支持代码库问答、内联改写和代理式改动，适合希望少切换窗口、在编辑现场完成大部分工作的开发者。 ai 编辑器 代码补全 代理模式 ide 在熟悉的编辑器里快速解释或改写代码 让代理在多个文件间完成同一项改动 用对话方式定位报错并生成修复方案','{"id":"cursor","name":"Cursor","tagline":"把 AI 对话、补全与多文件编辑放进熟悉的编辑器。","description":"围绕 AI 工作流打造的代码编辑器，支持代码库问答、内联改写和代理式改动，适合希望少切换窗口、在编辑现场完成大部分工作的开发者。","categoryId":"ai-coding","website":"https://cursor.com","tags":["AI 编辑器","代码补全","代理模式","IDE"],"platforms":["Web"],"pricing":"免费增值","icon":"Cu","accent":"#111111","featured":false,"useCases":["在熟悉的编辑器里快速解释或改写代码","让代理在多个文件间完成同一项改动","用对话方式定位报错并生成修复方案"],"highlights":["贴近 VS Code 的操作习惯，迁移成本较低","补全、对话与代理能力集中在同一界面","改动以前后差异呈现，便于逐段确认"],"logo":"/media/icons/cursor.svg"}',1) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('continue','Continue','ai-coding','开源免费',0,NULL,'continue 可自托管的 ide 编程助手，模型与规则都更可控。 开源的 ide 扩展，为 vs code 和 jetbrains 等环境接入对话、补全与自定义上下文，可连接本地模型、云端服务或团队自己的网关。 开源 ide 扩展 自定义模型 自托管 为团队统一 ai 补全和对话入口 在隐私敏感的代码库中接入本地模型 按项目沉淀提示词与上下文规则','{"id":"continue","name":"Continue","tagline":"可自托管的 IDE 编程助手，模型与规则都更可控。","description":"开源的 IDE 扩展，为 VS Code 和 JetBrains 等环境接入对话、补全与自定义上下文，可连接本地模型、云端服务或团队自己的网关。","categoryId":"ai-coding","website":"https://www.continue.dev","github":"https://github.com/continuedev/continue","tags":["开源","IDE 扩展","自定义模型","自托管"],"platforms":["Web"],"pricing":"开源免费","icon":"Co","accent":"#7C3AED","featured":false,"useCases":["为团队统一 AI 补全和对话入口","在隐私敏感的代码库中接入本地模型","按项目沉淀提示词与上下文规则"],"highlights":["模型提供方和密钥由使用者自行配置","支持自有服务与本地部署路径","开源实现便于审计和二次定制"],"logo":"/media/icons/continue.png"}',2) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('aider','Aider','ai-coding','开源免费',0,NULL,'aider 把仓库映射成上下文，在终端里结对改代码。 开源的终端 ai 结对编程工具，通过仓库地图和 git 集成进行批量修改，适合偏好命令行、重视差异审查与提交粒度的开发者。 终端 结对编程 git 开源 对一组相关文件做有针对性的批量修改 让模型基于仓库地图定位实现位置 把每次 ai 改动纳入清晰的 git 提交','{"id":"aider","name":"Aider","tagline":"把仓库映射成上下文，在终端里结对改代码。","description":"开源的终端 AI 结对编程工具，通过仓库地图和 Git 集成进行批量修改，适合偏好命令行、重视差异审查与提交粒度的开发者。","categoryId":"ai-coding","website":"https://aider.chat","github":"https://github.com/Aider-AI/aider","install":"python -m pip install aider-chat","tags":["终端","结对编程","Git","开源"],"platforms":["CLI"],"pricing":"开源免费","icon":"Ai","accent":"#2F6FEB","featured":false,"useCases":["对一组相关文件做有针对性的批量修改","让模型基于仓库地图定位实现位置","把每次 AI 改动纳入清晰的 Git 提交"],"highlights":["以仓库地图提供精简的代码上下文","自动生成改动差异，方便确认与回滚","支持多种模型与本地运行方式"],"logo":"/media/icons/aider.svg"}',3) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('ollama','Ollama','ai-coding','开源免费',0,NULL,'ollama 一条命令在本地拉起大模型，数据留在自己的机器上。 面向本地推理的模型运行器，提供简洁的命令行和本地 api，适合离线试验、隐私敏感内容以及不依赖云端服务的 ai 工作流。 本地模型 推理 离线 api 在没有稳定网络时试用开源模型 为内部工具提供本地模型接口 在不外传数据的前提下做文本实验','{"id":"ollama","name":"Ollama","tagline":"一条命令在本地拉起大模型，数据留在自己的机器上。","description":"面向本地推理的模型运行器，提供简洁的命令行和本地 API，适合离线试验、隐私敏感内容以及不依赖云端服务的 AI 工作流。","categoryId":"ai-coding","website":"https://ollama.com","github":"https://github.com/ollama/ollama","tags":["本地模型","推理","离线","API"],"platforms":["CLI"],"pricing":"开源免费","icon":"Ol","accent":"#1F2937","featured":false,"useCases":["在没有稳定网络时试用开源模型","为内部工具提供本地模型接口","在不外传数据的前提下做文本实验"],"highlights":["命令行拉取和运行模型的路径很直接","提供兼容常见接口约定的本地服务","模型与数据都留在自己控制的环境"],"logo":"/media/icons/ollama.png"}',4) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('vercel-ai-sdk','Vercel AI SDK','ai-coding','开源免费',0,NULL,'vercel ai sdk 用一套 typescript api 接入多家模型并流式输出。 面向 ai 应用的 typescript 工具包，统一模型调用、结构化输出、工具调用与流式界面，适合在 react 或 node 中快速搭建可替换模型的产品原型。 typescript 流式输出 多模型 工具调用 给聊天界面接上可流式返回的模型 在多家模型供应商之间切换对比 用结构化输出衔接前端表单与后端逻辑','{"id":"vercel-ai-sdk","name":"Vercel AI SDK","tagline":"用一套 TypeScript API 接入多家模型并流式输出。","description":"面向 AI 应用的 TypeScript 工具包，统一模型调用、结构化输出、工具调用与流式界面，适合在 React 或 Node 中快速搭建可替换模型的产品原型。","categoryId":"ai-coding","website":"https://ai-sdk.dev","github":"https://github.com/vercel/ai","install":"npm install ai","tags":["TypeScript","流式输出","多模型","工具调用"],"platforms":["Web"],"pricing":"开源免费","icon":"AI","accent":"#111111","featured":false,"useCases":["给聊天界面接上可流式返回的模型","在多家模型供应商之间切换对比","用结构化输出衔接前端表单与后端逻辑"],"highlights":["模型适配与 UI 流式状态有统一抽象","与 React、Next.js 等生态衔接顺畅","核心库开源，可逐步替换具体供应商"],"logo":"/media/icons/vercel-ai-sdk.svg"}',5) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('langgraph','LangGraph','ai-coding','开源免费',0,NULL,'langgraph 用图和状态编排可控、可恢复的智能体流程。 langchain 生态中的智能体编排框架，以有状态图组织多步推理、工具调用与人工介入，适合需要明确分支和检查点的复杂工作流。 智能体 状态图 编排 langchain 构建需要多步工具调用的智能体 在流程中加入人工审核或中断恢复 为不同意图设计清晰的图状分支','{"id":"langgraph","name":"LangGraph","tagline":"用图和状态编排可控、可恢复的智能体流程。","description":"LangChain 生态中的智能体编排框架，以有状态图组织多步推理、工具调用与人工介入，适合需要明确分支和检查点的复杂工作流。","categoryId":"ai-coding","website":"https://www.langchain.com/langgraph","github":"https://github.com/langchain-ai/langgraph","install":"pip install -U langgraph","tags":["智能体","状态图","编排","LangChain"],"platforms":["Web"],"pricing":"开源免费","icon":"LG","accent":"#1F6F5C","featured":false,"useCases":["构建需要多步工具调用的智能体","在流程中加入人工审核或中断恢复","为不同意图设计清晰的图状分支"],"highlights":["以状态图显式表达流程与跳转条件","支持持久化状态和中断后继续","与 LangChain 的模型及工具生态兼容"],"logo":"/media/icons/langgraph.png"}',6) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('react','React','frontend-ui','开源免费',0,NULL,'react 用组件思维构建可组合的现代 web 界面。 由 meta 维护的界面库，以组件和状态驱动视图更新。它不规定项目结构，适合从单页互动到大型产品逐步搭建自己的技术组合。 组件化 声明式 ui 生态成熟 hooks 搭建有大量状态交互的单页应用 把设计系统拆成可复用组件 借助成熟生态选择路由、状态与测试方案','{"id":"react","name":"React","tagline":"用组件思维构建可组合的现代 Web 界面。","description":"由 Meta 维护的界面库，以组件和状态驱动视图更新。它不规定项目结构，适合从单页互动到大型产品逐步搭建自己的技术组合。","categoryId":"frontend-ui","website":"https://react.dev","github":"https://github.com/facebook/react","install":"npm install react react-dom","tags":["组件化","声明式 UI","生态成熟","Hooks"],"platforms":["Web"],"pricing":"开源免费","icon":"Re","accent":"#087EA4","featured":false,"useCases":["搭建有大量状态交互的单页应用","把设计系统拆成可复用组件","借助成熟生态选择路由、状态与测试方案"],"highlights":["声明式更新模型让界面与状态对应","Hooks 把可复用逻辑留在组件附近","社区与工具链覆盖面广，问题容易检索"],"logo":"/media/icons/react.ico"}',7) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('vue','Vue','frontend-ui','开源免费',0,NULL,'vue 渐进式框架，也可以只在页面的一角开始。 渐进式前端框架，提供响应式系统、单文件组件和完整官方工具链。可以从增强一段静态页面开始，再逐步扩展到完整应用。 渐进式 响应式 单文件组件 模板语法 在服务端页面中局部增强交互 用单文件组件组织样式与逻辑 搭建中小型团队可快速上手的应用','{"id":"vue","name":"Vue","tagline":"渐进式框架，也可以只在页面的一角开始。","description":"渐进式前端框架，提供响应式系统、单文件组件和完整官方工具链。可以从增强一段静态页面开始，再逐步扩展到完整应用。","categoryId":"frontend-ui","website":"https://vuejs.org","github":"https://github.com/vuejs/core","install":"npm create vue@latest","tags":["渐进式","响应式","单文件组件","模板语法"],"platforms":["Web"],"pricing":"开源免费","icon":"Vu","accent":"#42B883","featured":false,"useCases":["在服务端页面中局部增强交互","用单文件组件组织样式与逻辑","搭建中小型团队可快速上手的应用"],"highlights":["模板、脚本与样式可以集中在同一文件","响应式系统让状态更新表达直观","官方路由、状态和构建工具衔接完整"],"logo":"/media/icons/vue.svg"}',8) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('vite','Vite','frontend-ui','开源免费',0,NULL,'vite 围绕原生 esm 的快启动开发服务器与构建工具。 面向现代浏览器的开发与构建工具，借助原生 es 模块在开发时按需编译，并用 rollup 等方案完成生产构建，适合多数前端框架。 构建工具 开发服务器 esm 插件生态 为 react 或 vue 项目提供快速开发环境 通过插件定制资源处理与构建流程 为组件库配置独立的演示和打包','{"id":"vite","name":"Vite","tagline":"围绕原生 ESM 的快启动开发服务器与构建工具。","description":"面向现代浏览器的开发与构建工具，借助原生 ES 模块在开发时按需编译，并用 Rollup 等方案完成生产构建，适合多数前端框架。","categoryId":"frontend-ui","website":"https://vite.dev","github":"https://github.com/vitejs/vite","install":"npm create vite@latest","tags":["构建工具","开发服务器","ESM","插件生态"],"platforms":["Web"],"pricing":"开源免费","icon":"Vi","accent":"#646CFF","featured":false,"useCases":["为 React 或 Vue 项目提供快速开发环境","通过插件定制资源处理与构建流程","为组件库配置独立的演示和打包"],"highlights":["开发阶段按需编译，启动等待更少","配置相对精简，常见框架都有模板","生产构建与插件生态选择丰富"],"logo":"/media/icons/vite.svg"}',9) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('nextjs','Next.js','frontend-ui','开源免费',1,NULL,'next.js react 全栈框架，把页面、路由与数据获取放在一起。 建立在 react 之上的全栈框架，提供文件路由、服务端渲染、静态生成与 route handlers，适合需要兼顾首屏、seo 和前后端协作的产品。 react 全栈 ssr 文件路由 构建需要搜索收录的内容站 在同一仓库中编写页面与接口 用服务端与客户端组件拆分数据边界','{"id":"nextjs","name":"Next.js","tagline":"React 全栈框架，把页面、路由与数据获取放在一起。","description":"建立在 React 之上的全栈框架，提供文件路由、服务端渲染、静态生成与 Route Handlers，适合需要兼顾首屏、SEO 和前后端协作的产品。","categoryId":"frontend-ui","website":"https://nextjs.org","github":"https://github.com/vercel/next.js","install":"npx create-next-app@latest","tags":["React","全栈","SSR","文件路由"],"platforms":["Web"],"pricing":"开源免费","icon":"N","accent":"#111111","featured":true,"useCases":["构建需要搜索收录的内容站","在同一仓库中编写页面与接口","用服务端与客户端组件拆分数据边界"],"highlights":["文件系统即路由，结构一眼可读","支持多种渲染与缓存策略组合","部署选择和社区资料都比较成熟"],"logo":"/media/icons/nextjs.ico"}',10) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('tailwindcss','Tailwind CSS','frontend-ui','开源免费',0,NULL,'tailwind css 用实用类在结构里直接表达样式与设计约束。 实用优先的 css 框架，让颜色、间距与响应式规则直接出现在标记旁。配合设计令牌和组件抽象，可以保持快速迭代时的一致性。 css 实用类 设计令牌 响应式 快速搭建风格统一的产品界面 通过令牌约束间距、色彩与字体 在组件中直接处理响应式状态','{"id":"tailwindcss","name":"Tailwind CSS","tagline":"用实用类在结构里直接表达样式与设计约束。","description":"实用优先的 CSS 框架，让颜色、间距与响应式规则直接出现在标记旁。配合设计令牌和组件抽象，可以保持快速迭代时的一致性。","categoryId":"frontend-ui","website":"https://tailwindcss.com","github":"https://github.com/tailwindlabs/tailwindcss","install":"npm install tailwindcss @tailwindcss/vite","tags":["CSS","实用类","设计令牌","响应式"],"platforms":["Web"],"pricing":"开源免费","icon":"Tw","accent":"#0EA5E9","featured":false,"useCases":["快速搭建风格统一的产品界面","通过令牌约束间距、色彩与字体","在组件中直接处理响应式状态"],"highlights":["样式与结构相邻，修改上下文集中","按项目需要裁剪生成，减少冗余样式","设计令牌适合沉淀长期视觉规则"],"logo":"/media/icons/tailwindcss.ico"}',11) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('shadcn-ui','shadcn/ui','frontend-ui','开源免费',1,NULL,'shadcn/ui 可复制进项目的组件源码，而不是另一层黑盒依赖。 基于 radix ui 与 tailwind css 的组件集合，通过命令行把源码加入项目。组件归项目所有，可以按设计系统和业务需要直接修改。 react 组件 源码可控 tailwind radix ui 快速拼出带有基础交互的产品骨架 在已有设计系统上二次调整组件 减少通用弹窗、菜单和表单的重复实现','{"id":"shadcn-ui","name":"shadcn/ui","tagline":"可复制进项目的组件源码，而不是另一层黑盒依赖。","description":"基于 Radix UI 与 Tailwind CSS 的组件集合，通过命令行把源码加入项目。组件归项目所有，可以按设计系统和业务需要直接修改。","categoryId":"frontend-ui","website":"https://ui.shadcn.com","github":"https://github.com/shadcn-ui/ui","install":"npx shadcn@latest init","tags":["React 组件","源码可控","Tailwind","Radix UI"],"platforms":["Web"],"pricing":"开源免费","icon":"Sh","accent":"#18181B","featured":true,"useCases":["快速拼出带有基础交互的产品骨架","在已有设计系统上二次调整组件","减少通用弹窗、菜单和表单的重复实现"],"highlights":["源码进入仓库，不必适配组件库黑盒","交互底座来自 Radix 的可访问性能力","样式使用 Tailwind，和现有令牌容易融合"],"logo":"/media/icons/shadcn-ui.png"}',12) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('radix-ui','Radix UI','frontend-ui','开源免费',0,'radix-focus','radix ui 给自定义组件补上可靠的无样式交互与可访问性。 一套无样式 react 组件原语，处理弹窗、菜单、选择器等复杂交互中的焦点、键盘与无障碍细节，视觉层完全留给项目自己决定。 无样式 可访问性 react 交互原语 实现需要键盘和焦点管理的对话框 打造完全贴合品牌的选择器与菜单 为设计系统提供稳定的交互底座','{"id":"radix-ui","name":"Radix UI","tagline":"给自定义组件补上可靠的无样式交互与可访问性。","description":"一套无样式 React 组件原语，处理弹窗、菜单、选择器等复杂交互中的焦点、键盘与无障碍细节，视觉层完全留给项目自己决定。","categoryId":"frontend-ui","website":"https://www.radix-ui.com","github":"https://github.com/radix-ui/primitives","install":"npm install @radix-ui/react-dialog","tags":["无样式","可访问性","React","交互原语"],"platforms":["Web"],"pricing":"开源免费","icon":"Rx","accent":"#6E56CF","featured":false,"useCases":["实现需要键盘和焦点管理的对话框","打造完全贴合品牌的选择器与菜单","为设计系统提供稳定的交互底座"],"highlights":["组件默认考虑键盘导航与焦点归还","不附带视觉样式，方便自由设计","复杂交互拆成可组合的子组件"],"logo":"/media/icons/radix-ui.svg","demoId":"radix-focus"}',13) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('typescript','TypeScript','frontend-ui','开源免费',0,'tsc-diagnostics','typescript 为 javascript 加上可检查的类型，让重构更有底气。 微软维护的 javascript 超集，通过静态类型和编辑器提示提前暴露接口误用，适合在多人协作或持续演进的项目中建立明确边界。 静态类型 javascript 编辑器提示 重构 为共享组件和 api 约定类型 在重构时稳定追踪调用点 把编辑器变成实时的接口检查器','{"id":"typescript","name":"TypeScript","tagline":"为 JavaScript 加上可检查的类型，让重构更有底气。","description":"微软维护的 JavaScript 超集，通过静态类型和编辑器提示提前暴露接口误用，适合在多人协作或持续演进的项目中建立明确边界。","categoryId":"frontend-ui","website":"https://www.typescriptlang.org","github":"https://github.com/microsoft/TypeScript","install":"npm install -D typescript","tags":["静态类型","JavaScript","编辑器提示","重构"],"platforms":["Web"],"pricing":"开源免费","icon":"TS","accent":"#3178C6","featured":false,"useCases":["为共享组件和 API 约定类型","在重构时稳定追踪调用点","把编辑器变成实时的接口检查器"],"highlights":["类型信息与编辑器补全深度结合","渐进式接入，允许从 JavaScript 过渡","广泛支持主流框架与构建工具"],"logo":"/media/icons/typescript.png","demoId":"tsc-diagnostics"}',14) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('zod','Zod','frontend-ui','开源免费',0,'zod-schema','zod 用 typescript 声明一次结构，同时得到运行时校验。 类型优先的数据校验库，用一套 schema 同时推导静态类型并在运行时验证输入，适合表单、接口边界和环境变量等不可信数据入口。 数据校验 typescript schema 运行时 校验表单提交的输入结构 为接口请求和响应定义共享 schema 在启动时检查环境变量是否完整','{"id":"zod","name":"Zod","tagline":"用 TypeScript 声明一次结构，同时得到运行时校验。","description":"类型优先的数据校验库，用一套 schema 同时推导静态类型并在运行时验证输入，适合表单、接口边界和环境变量等不可信数据入口。","categoryId":"frontend-ui","website":"https://zod.dev","github":"https://github.com/colinhacks/zod","install":"npm install zod","tags":["数据校验","TypeScript","Schema","运行时"],"platforms":["Web"],"pricing":"开源免费","icon":"Z","accent":"#3068B7","featured":false,"useCases":["校验表单提交的输入结构","为接口请求和响应定义共享 schema","在启动时检查环境变量是否完整"],"highlights":["从 schema 自动推导 TypeScript 类型","校验失败时能提供结构化错误路径","组合式 API 方便复用字段规则"],"logo":"/media/icons/zod.png","demoId":"zod-schema"}',15) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('tanstack-query','TanStack Query','frontend-ui','开源免费',0,'tanstack-cache','tanstack query 把服务端状态、缓存与请求生命周期收进一套 hooks。 面向 react 等服务端状态的异步数据管理库，处理请求、缓存、失效、重试与分页，让 ui 状态和远端数据保持清晰边界。 数据请求 缓存 hooks 服务端状态 为列表和详情页管理请求缓存 在数据变更后精准刷新相关查询 处理加载、错误和分页状态','{"id":"tanstack-query","name":"TanStack Query","tagline":"把服务端状态、缓存与请求生命周期收进一套 hooks。","description":"面向 React 等服务端状态的异步数据管理库，处理请求、缓存、失效、重试与分页，让 UI 状态和远端数据保持清晰边界。","categoryId":"frontend-ui","website":"https://tanstack.com/query/latest","github":"https://github.com/TanStack/query","install":"npm install @tanstack/react-query","tags":["数据请求","缓存","Hooks","服务端状态"],"platforms":["Web"],"pricing":"开源免费","icon":"TQ","accent":"#E85D3F","featured":false,"useCases":["为列表和详情页管理请求缓存","在数据变更后精准刷新相关查询","处理加载、错误和分页状态"],"highlights":["把服务端状态与本地 UI 状态分开管理","内置失效、重试和并发控制能力","支持偏好在客户端或服务端预取"],"logo":"/media/icons/tanstack-query.svg","demoId":"tanstack-cache"}',16) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('zustand','Zustand','frontend-ui','开源免费',0,'zustand-store','zustand 轻量、直白的 react 客户端状态容器。 基于 hooks 的小型状态管理库，用极少的样板代码创建共享 store，适合主题、筛选、编辑器状态等客户端交互，而不是替代服务端缓存。 状态管理 react 轻量 hooks 保存跨组件的筛选与主题状态 管理编辑器中多个面板的交互状态 为中小型应用提供轻量的共享 store','{"id":"zustand","name":"Zustand","tagline":"轻量、直白的 React 客户端状态容器。","description":"基于 hooks 的小型状态管理库，用极少的样板代码创建共享 store，适合主题、筛选、编辑器状态等客户端交互，而不是替代服务端缓存。","categoryId":"frontend-ui","website":"https://zustand.docs.pmnd.rs","github":"https://github.com/pmndrs/zustand","install":"npm install zustand","tags":["状态管理","React","轻量","Hooks"],"platforms":["Web"],"pricing":"开源免费","icon":"Zu","accent":"#7A5C3E","featured":false,"demoId":"zustand-store","useCases":["保存跨组件的筛选与主题状态","管理编辑器中多个面板的交互状态","为中小型应用提供轻量的共享 store"],"highlights":["创建 store 所需样板很少","按选择器订阅，减少无关重渲染","不依赖特定框架的复杂上下文层"],"logo":"/media/icons/zustand.png"}',17) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('lucide','Lucide','frontend-ui','开源免费',0,NULL,'lucide 风格统一的开放图标库，随组件一起按需引入。 以一致的线条风格提供大量开放图标，支持 react、vue 等框架与 svg 使用方式。图标以组件形式引入，适合和界面控件一起维护。 图标 svg react 开源 为工具栏和操作按钮补齐图标 在设计系统中统一线条与尺寸 按需引入图标，控制打包体积','{"id":"lucide","name":"Lucide","tagline":"风格统一的开放图标库，随组件一起按需引入。","description":"以一致的线条风格提供大量开放图标，支持 React、Vue 等框架与 SVG 使用方式。图标以组件形式引入，适合和界面控件一起维护。","categoryId":"frontend-ui","website":"https://lucide.dev","github":"https://github.com/lucide-icons/lucide","install":"npm install lucide-react","tags":["图标","SVG","React","开源"],"platforms":["Web"],"pricing":"开源免费","icon":"Lu","accent":"#E05252","featured":false,"useCases":["为工具栏和操作按钮补齐图标","在设计系统中统一线条与尺寸","按需引入图标，控制打包体积"],"highlights":["图标几何与描边规则保持一致","可随文字颜色继承 currentColor","多框架包与原始 SVG 都可用"],"logo":"/media/icons/lucide.ico"}',18) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('iconify','Iconify','frontend-ui','开源免费',0,NULL,'iconify 一套接口检索并组合几十个图标集。 开放的图标聚合与组件方案，可以按需加载多个图标集，也支持在自己的网站或设计工具中统一搜索和引用。 图标集 按需加载 统一检索 设计工具 在多个图标风格之间快速比选 只加载实际使用的图标数据 让设计和开发引用同一图标来源','{"id":"iconify","name":"Iconify","tagline":"一套接口检索并组合几十个图标集。","description":"开放的图标聚合与组件方案，可以按需加载多个图标集，也支持在自己的网站或设计工具中统一搜索和引用。","categoryId":"frontend-ui","website":"https://iconify.design","github":"https://github.com/iconify/iconify","install":"npm install @iconify/react","tags":["图标集","按需加载","统一检索","设计工具"],"platforms":["Web"],"pricing":"开源免费","icon":"Ic","accent":"#1769AA","featured":false,"useCases":["在多个图标风格之间快速比选","只加载实际使用的图标数据","让设计和开发引用同一图标来源"],"highlights":["聚合大量图标集，检索入口统一","按图标按需获取，避免整套引入","覆盖多种前端框架和设计插件"],"logo":"/media/icons/iconify.svg"}',19) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('motion','Motion','motion','免费增值',1,'motion-layout','motion 为 react 界面加入细顺的进入、布局与手势动画。 原 framer motion 团队维护的动画库，提供声明式动画、布局过渡、手势与弹簧物理，适合把界面状态变化表达成自然的运动。 react 动画 弹簧 布局动画 手势 为卡片和列表加入进入退出动画 在布局变化时保持元素连贯 实现拖拽和手势驱动的界面反馈','{"id":"motion","name":"Motion","tagline":"为 React 界面加入细顺的进入、布局与手势动画。","description":"原 Framer Motion 团队维护的动画库，提供声明式动画、布局过渡、手势与弹簧物理，适合把界面状态变化表达成自然的运动。","categoryId":"motion","website":"https://motion.dev","github":"https://github.com/motiondivision/motion","install":"npm install motion","tags":["React 动画","弹簧","布局动画","手势"],"platforms":["Web"],"pricing":"免费增值","icon":"Mo","accent":"#E64A4A","featured":true,"demoId":"motion-layout","useCases":["为卡片和列表加入进入退出动画","在布局变化时保持元素连贯","实现拖拽和手势驱动的界面反馈"],"highlights":["声明式 API 与 React 状态自然衔接","布局动画可减少手工计算位置","弹簧与手势能力适合精细交互"],"logo":"/media/icons/motion.svg"}',20) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('gsap','GSAP','motion','免费使用',0,'gsap-timeline','gsap 面向时间线与精细节奏的 web 动画工具带。 成熟的 javascript 动画平台，以时间线、缓动和滚动触发见长。官方说明当前全部插件可按免费使用的标准许可获取，具体授权范围与条款以官方许可为准。 时间线 滚动动画 缓动 javascript 编排多元素依次出场的分镜 把动画绑定到滚动进度 在原生 js 或框架中复用时间线','{"id":"gsap","name":"GSAP","tagline":"面向时间线与精细节奏的 Web 动画工具带。","description":"成熟的 JavaScript 动画平台，以时间线、缓动和滚动触发见长。官方说明当前全部插件可按免费使用的标准许可获取，具体授权范围与条款以官方许可为准。","categoryId":"motion","website":"https://gsap.com","github":"https://github.com/greensock/GSAP","install":"npm install gsap","tags":["时间线","滚动动画","缓动","JavaScript"],"platforms":["Web"],"pricing":"免费使用","icon":"Gs","accent":"#6E9F18","featured":false,"demoId":"gsap-timeline","useCases":["编排多元素依次出场的分镜","把动画绑定到滚动进度","在原生 JS 或框架中复用时间线"],"highlights":["时间线能把复杂节奏拆得清楚","缓动与播放控制选项丰富","官方称全部插件可免费使用，授权以标准许可为准"],"logo":"/media/icons/gsap.svg"}',21) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('threejs','Three.js','motion','开源免费',0,'three-instanced','three.js 在浏览器里直接搭建 3d 场景与实时渲染。 基于 webgl 的 3d 图形库，提供相机、材质、光照和几何体的高层抽象，适合产品展示、互动视觉和数据空间化等场景。 3d webgl 实时渲染 canvas 制作可旋转的产品 3d 展示 搭建带有材质和光照的场景预览 用粒子或实例化几何做动态背景','{"id":"threejs","name":"Three.js","tagline":"在浏览器里直接搭建 3D 场景与实时渲染。","description":"基于 WebGL 的 3D 图形库，提供相机、材质、光照和几何体的高层抽象，适合产品展示、互动视觉和数据空间化等场景。","categoryId":"motion","website":"https://threejs.org","github":"https://github.com/mrdoob/three.js","install":"npm install three","tags":["3D","WebGL","实时渲染","Canvas"],"platforms":["Web"],"pricing":"开源免费","icon":"Th","accent":"#111111","featured":false,"demoId":"three-instanced","useCases":["制作可旋转的产品 3D 展示","搭建带有材质和光照的场景预览","用粒子或实例化几何做动态背景"],"highlights":["3D 场景的核心对象抽象完整","材质、后期和加载器生态丰富","示例与社区资料覆盖大量常见需求"],"logo":"/media/icons/threejs.ico"}',22) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('swiper','Swiper','motion','开源免费',0,'swiper-pager','swiper 成熟的多端滑动组件，轮播也能有细节。 不依赖框架的滑动与轮播库，支持触摸、分页、循环和无障碍配置，可配合 react、vue 等使用，适合移动端画廊和内容切换。 轮播 触摸手势 移动端 无依赖 实现移动端商品或图片轮播 为内容区加入触摸滑动切换 搭建多断点的响应式画廊','{"id":"swiper","name":"Swiper","tagline":"成熟的多端滑动组件，轮播也能有细节。","description":"不依赖框架的滑动与轮播库，支持触摸、分页、循环和无障碍配置，可配合 React、Vue 等使用，适合移动端画廊和内容切换。","categoryId":"motion","website":"https://swiperjs.com","github":"https://github.com/nolimits4web/swiper","install":"npm install swiper","tags":["轮播","触摸手势","移动端","无依赖"],"platforms":["Web","Mobile"],"pricing":"开源免费","icon":"Sw","accent":"#6338F6","featured":false,"useCases":["实现移动端商品或图片轮播","为内容区加入触摸滑动切换","搭建多断点的响应式画廊"],"highlights":["触摸、鼠标和键盘操作路径完整","模块化引入，按功能控制体积","提供丰富的分页和切换效果选项"],"logo":"/media/icons/swiper.svg","demoId":"swiper-pager"}',23) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('dnd-kit','dnd-kit','motion','开源免费',0,'dnd-board','dnd-kit 为 react 提供可访问、可组合的拖拽原语。 面向 react 的拖拽工具包，用传感器、碰撞检测与可排序模块组合交互，兼顾键盘操作和屏幕阅读器反馈。 拖拽 react 可访问性 排序 实现跨列看板或排序列表 为拖拽操作补充键盘路径 自定义拖拽预览与碰撞策略','{"id":"dnd-kit","name":"dnd-kit","tagline":"为 React 提供可访问、可组合的拖拽原语。","description":"面向 React 的拖拽工具包，用传感器、碰撞检测与可排序模块组合交互，兼顾键盘操作和屏幕阅读器反馈。","categoryId":"motion","website":"https://dndkit.com","github":"https://github.com/clauderic/dnd-kit","install":"npm install @dnd-kit/core @dnd-kit/sortable","tags":["拖拽","React","可访问性","排序"],"platforms":["Web"],"pricing":"开源免费","icon":"Dn","accent":"#5C6470","featured":false,"demoId":"dnd-board","useCases":["实现跨列看板或排序列表","为拖拽操作补充键盘路径","自定义拖拽预览与碰撞策略"],"highlights":["默认提供键盘传感器和多类传感器","模块化结构便于按场景组合","对激活、悬停和放置反馈有明确状态"],"logo":"/media/icons/dnd-kit.png"}',24) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('echarts','ECharts','charts','开源免费',1,'echarts-dataset','echarts 配置驱动的全场景图表库，中文生态扎实。 apache 开源的可视化库，覆盖折线、柱状、地图、关系图等大量图表类型，适合需要在同一套配置体系里完成常规与复杂可视化的项目。 图表库 apache 地图 仪表盘 搭建多图表联动的数据看板 用地图和关系图表达空间与网络数据 在中文项目中快速找到配置与示例','{"id":"echarts","name":"ECharts","tagline":"配置驱动的全场景图表库，中文生态扎实。","description":"Apache 开源的可视化库，覆盖折线、柱状、地图、关系图等大量图表类型，适合需要在同一套配置体系里完成常规与复杂可视化的项目。","categoryId":"charts","website":"https://echarts.apache.org","github":"https://github.com/apache/echarts","install":"npm install echarts","tags":["图表库","Apache","地图","仪表盘"],"platforms":["Web"],"pricing":"开源免费","icon":"Ec","accent":"#AA344D","featured":true,"demoId":"echarts-dataset","useCases":["搭建多图表联动的数据看板","用地图和关系图表达空间与网络数据","在中文项目中快速找到配置与示例"],"highlights":["图表类型覆盖广，配置体系统一","交互组件和渲染模式选择成熟","中文文档与社区资料充足"],"logo":"/media/icons/echarts.png"}',25) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('d3','D3','charts','开源免费',0,'d3-datajoin','d3 用数据绑定的底层原语，画任何你想要的图。 数据驱动文档的底层可视化工具集，提供比例尺、形状生成、数据变换和 dom/svg 操作，适合需要高度定制表达的可视化项目。 数据可视化 svg 比例尺 定制 制作高度定制的编辑型图表 用比例尺和路径生成自定义视觉 做数据驱动的过渡与交互编排','{"id":"d3","name":"D3","tagline":"用数据绑定的底层原语，画任何你想要的图。","description":"数据驱动文档的底层可视化工具集，提供比例尺、形状生成、数据变换和 DOM/SVG 操作，适合需要高度定制表达的可视化项目。","categoryId":"charts","website":"https://d3js.org","github":"https://github.com/d3/d3","install":"npm install d3","tags":["数据可视化","SVG","比例尺","定制"],"platforms":["Web"],"pricing":"开源免费","icon":"D3","accent":"#E59A3A","featured":false,"demoId":"d3-datajoin","useCases":["制作高度定制的编辑型图表","用比例尺和路径生成自定义视觉","做数据驱动的过渡与交互编排"],"highlights":["原语组合自由，不被固定图表类型限制","比例尺、形状与数据变换能力完整","适合作为其他图表库的底层基础"],"logo":"/media/icons/d3.svg"}',26) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('chartjs','Chart.js','charts','开源免费',0,'chartjs-mixed','chart.js 基于 canvas、上手很快的轻量图表方案。 提供常见图表类型与动画的 canvas 图表库，配置直观、体积可控，适合仪表盘中的常规统计图和需要快速集成的项目。 canvas 柱状图 折线图 轻量 给后台快速加入统计图 实现基础折线与柱状对比 在移动端展示轻量图表','{"id":"chartjs","name":"Chart.js","tagline":"基于 Canvas、上手很快的轻量图表方案。","description":"提供常见图表类型与动画的 Canvas 图表库，配置直观、体积可控，适合仪表盘中的常规统计图和需要快速集成的项目。","categoryId":"charts","website":"https://www.chartjs.org","github":"https://github.com/chartjs/Chart.js","install":"npm install chart.js","tags":["Canvas","柱状图","折线图","轻量"],"platforms":["Web"],"pricing":"开源免费","icon":"Ch","accent":"#D64B68","featured":false,"demoId":"chartjs-mixed","useCases":["给后台快速加入统计图","实现基础折线与柱状对比","在移动端展示轻量图表"],"highlights":["常见图表的默认配置直观","渲染基于 Canvas，适合较大数据量的绘制","支持响应式容器与交互动画"],"logo":"/media/icons/chartjs.ico"}',27) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('recharts','Recharts','charts','开源免费',0,'recharts-brush','recharts 用 react 组件组合出声明式图表。 基于 react 与 d3 模块构建的图表库，用 jsx 组合坐标轴、图形和图例，适合希望图表也遵循 react 数据流与组件结构的界面。 react 声明式 图表 svg 在 react 仪表盘中组合常规图表 用组件 props 控制坐标与样式 让图表融入现有设计系统','{"id":"recharts","name":"Recharts","tagline":"用 React 组件组合出声明式图表。","description":"基于 React 与 D3 模块构建的图表库，用 JSX 组合坐标轴、图形和图例，适合希望图表也遵循 React 数据流与组件结构的界面。","categoryId":"charts","website":"https://recharts.org","github":"https://github.com/recharts/recharts","install":"npm install recharts","tags":["React","声明式","图表","SVG"],"platforms":["Web"],"pricing":"开源免费","icon":"Rc","accent":"#1F8A96","featured":false,"demoId":"recharts-brush","useCases":["在 React 仪表盘中组合常规图表","用组件 props 控制坐标与样式","让图表融入现有设计系统"],"highlights":["图表结构以 JSX 表达，可读性较好","与 React 状态和组件复用方式一致","内置常用图表与响应式容器"],"logo":"/media/icons/recharts.png"}',28) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('nivo','Nivo','charts','开源免费',0,NULL,'nivo 在 react 中快速得到完成度很高的数据可视化。 提供丰富图表组件和主题能力的 react 可视化库，默认视觉较为完整，也支持服务端渲染，适合追求成品感和统一外观的项目。 react 主题化 图表 ssr 搭建视觉完成度较高的图表页面 用统一主题管理多类图表 在 react 服务端渲染中生成图表','{"id":"nivo","name":"Nivo","tagline":"在 React 中快速得到完成度很高的数据可视化。","description":"提供丰富图表组件和主题能力的 React 可视化库，默认视觉较为完整，也支持服务端渲染，适合追求成品感和统一外观的项目。","categoryId":"charts","website":"https://nivo.rocks","github":"https://github.com/plouc/nivo","install":"npm install @nivo/bar","tags":["React","主题化","图表","SSR"],"platforms":["Web"],"pricing":"开源免费","icon":"Ni","accent":"#E8794A","featured":false,"useCases":["搭建视觉完成度较高的图表页面","用统一主题管理多类图表","在 React 服务端渲染中生成图表"],"highlights":["组件覆盖常见与进阶图表类型","主题与动效配置较丰富","支持服务端渲染等工程场景"],"logo":"/media/icons/nivo.png"}',29) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('cloudflare-workers','Cloudflare Workers','backend','免费增值',1,NULL,'cloudflare workers 把轻量服务部署到全球边缘网络的运行时。 cloudflare 的无服务器运行时，基于 web 标准 api，适合把 api、页面与轻量业务逻辑部署到靠近用户的边缘节点，并与 d1、r2 等服务组合。 无服务器 边缘计算 runtime cloudflare 部署轻量 api 与全栈页面 在边缘完成鉴权或内容变换 与 d1、r2 组成小团队的低运维后端','{"id":"cloudflare-workers","name":"Cloudflare Workers","tagline":"把轻量服务部署到全球边缘网络的运行时。","description":"Cloudflare 的无服务器运行时，基于 Web 标准 API，适合把 API、页面与轻量业务逻辑部署到靠近用户的边缘节点，并与 D1、R2 等服务组合。","categoryId":"backend","website":"https://workers.cloudflare.com","github":"https://github.com/cloudflare/workers-sdk","install":"npm create cloudflare@latest","tags":["无服务器","边缘计算","Runtime","Cloudflare"],"platforms":["Web"],"pricing":"免费增值","icon":"Wk","accent":"#F48120","featured":true,"useCases":["部署轻量 API 与全栈页面","在边缘完成鉴权或内容变换","与 D1、R2 组成小团队的低运维后端"],"highlights":["接近 Web 标准的运行时与 API","本地开发与部署工具链集成","按使用量扩展，适合从小项目起步"],"logo":"/media/icons/cloudflare-workers.svg"}',30) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('d1','D1','backend','免费增值',0,'d1-sql','d1 与 workers 贴近的 sqlite 风格边缘数据库。 cloudflare 提供的托管 sql 数据库，基于 sqlite，可与 workers 直接绑定，适合中小规模数据、原型和需要低运维的应用后端。 sqlite 边缘数据库 cloudflare sql 为 workers 应用提供关系数据存储 快速搭建无需独立数据库运维的原型 保存目录、评论或轻量业务数据','{"id":"d1","name":"D1","tagline":"与 Workers 贴近的 SQLite 风格边缘数据库。","description":"Cloudflare 提供的托管 SQL 数据库，基于 SQLite，可与 Workers 直接绑定，适合中小规模数据、原型和需要低运维的应用后端。","categoryId":"backend","website":"https://developers.cloudflare.com/d1/","install":"npx wrangler d1 create my-db","tags":["SQLite","边缘数据库","Cloudflare","SQL"],"platforms":["Web"],"pricing":"免费增值","icon":"D1","accent":"#D97706","featured":false,"useCases":["为 Workers 应用提供关系数据存储","快速搭建无需独立数据库运维的原型","保存目录、评论或轻量业务数据"],"highlights":["通过绑定直接接入 Workers","沿用熟悉的 SQL 与 SQLite 习惯","支持本地开发与迁移管理"],"logo":"/media/icons/d1.svg","demoId":"d1-sql"}',31) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('r2','R2','backend','免费增值',0,'r2-range','r2 无需出站流量费的兼容 s3 对象存储。 cloudflare 的对象存储服务，兼容 s3 接口且不收取出站流量费，适合存放图片、媒体与构建产物，并与 workers 组合提供内容服务。 对象存储 s3 兼容 媒体 cloudflare 托管站点图片和视频资源 通过 workers 提供鉴权后的文件访问 备份构建产物与用户上传内容','{"id":"r2","name":"R2","tagline":"无需出站流量费的兼容 S3 对象存储。","description":"Cloudflare 的对象存储服务，兼容 S3 接口且不收取出站流量费，适合存放图片、媒体与构建产物，并与 Workers 组合提供内容服务。","categoryId":"backend","website":"https://developers.cloudflare.com/r2/","install":"npx wrangler r2 bucket create my-bucket","tags":["对象存储","S3 兼容","媒体","Cloudflare"],"platforms":["Web"],"pricing":"免费增值","icon":"R2","accent":"#C2410C","featured":false,"useCases":["托管站点图片和视频资源","通过 Workers 提供鉴权后的文件访问","备份构建产物与用户上传内容"],"highlights":["兼容常见 S3 客户端与工作流","出站流量不单独计费，媒体分发成本清晰","与 Workers 的绑定方式简单直接"],"logo":"/media/icons/r2.svg","demoId":"r2-range"}',32) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('hono','Hono','backend','开源免费',0,'hono-router','hono 小而快的 web 框架，优先适配边缘运行时。 轻量的 typescript web 框架，基于 fetch api，提供路由、中间件和类型辅助，适合在 workers、bun、node 等运行时共享同一套接口代码。 web 框架 typescript 边缘 中间件 在 workers 上搭建类型安全的 api 编写可复用的小型后端服务 为多种运行时维护一套路由逻辑','{"id":"hono","name":"Hono","tagline":"小而快的 Web 框架，优先适配边缘运行时。","description":"轻量的 TypeScript Web 框架，基于 Fetch API，提供路由、中间件和类型辅助，适合在 Workers、Bun、Node 等运行时共享同一套接口代码。","categoryId":"backend","website":"https://hono.dev","github":"https://github.com/honojs/hono","install":"npm create hono@latest","tags":["Web 框架","TypeScript","边缘","中间件"],"platforms":["Web"],"pricing":"开源免费","icon":"Ho","accent":"#E36002","featured":false,"useCases":["在 Workers 上搭建类型安全的 API","编写可复用的小型后端服务","为多种运行时维护一套路由逻辑"],"highlights":["体积小，启动开销低","路由与 RPC 类型体验顺滑","中间件生态覆盖鉴权、缓存和日志"],"logo":"/media/icons/hono.ico","demoId":"hono-router"}',33) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('drizzle','Drizzle ORM','backend','开源免费',0,'drizzle-join','drizzle orm 贴近 sql 的 typescript orm，类型与迁移一起管。 轻量的 typescript orm，以 schema 定义表结构并提供接近 sql 的查询构建器，适合想保留 sql 掌控感又需要类型检查的项目。 orm typescript sql 迁移 为 workers 与 d1 编写类型安全查询 在保留 sql 思维的同时减少手写错误 维护受版本管理的数据库迁移','{"id":"drizzle","name":"Drizzle ORM","tagline":"贴近 SQL 的 TypeScript ORM，类型与迁移一起管。","description":"轻量的 TypeScript ORM，以 schema 定义表结构并提供接近 SQL 的查询构建器，适合想保留 SQL 掌控感又需要类型检查的项目。","categoryId":"backend","website":"https://orm.drizzle.team","github":"https://github.com/drizzle-team/drizzle-orm","install":"npm install drizzle-orm","tags":["ORM","TypeScript","SQL","迁移"],"platforms":["Web"],"pricing":"开源免费","icon":"Dr","accent":"#6B8E00","featured":false,"useCases":["为 Workers 与 D1 编写类型安全查询","在保留 SQL 思维的同时减少手写错误","维护受版本管理的数据库迁移"],"highlights":["查询表达接近 SQL，学习路径短","schema 推导类型，前后端共享更稳","支持多种数据库与迁移工具"],"logo":"/media/icons/drizzle.ico","demoId":"drizzle-join"}',34) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('prisma','Prisma','backend','开源免费',0,NULL,'prisma 从 schema 出发的 typescript 数据访问与迁移工具。 以声明式 schema 为中心的 orm 与数据库工具，生成类型安全客户端并提供迁移命令，适合希望统一数据模型与开发体验的 node.js 项目。 orm schema 迁移 typescript 从数据模型生成类型安全客户端 为团队建立统一的迁移流程 在 node 服务中快速组织关系查询','{"id":"prisma","name":"Prisma","tagline":"从 schema 出发的 TypeScript 数据访问与迁移工具。","description":"以声明式 schema 为中心的 ORM 与数据库工具，生成类型安全客户端并提供迁移命令，适合希望统一数据模型与开发体验的 Node.js 项目。","categoryId":"backend","website":"https://www.prisma.io","github":"https://github.com/prisma/prisma","install":"npm install prisma --save-dev","tags":["ORM","Schema","迁移","TypeScript"],"platforms":["Web"],"pricing":"开源免费","icon":"Pr","accent":"#2D3748","featured":false,"useCases":["从数据模型生成类型安全客户端","为团队建立统一的迁移流程","在 Node 服务中快速组织关系查询"],"highlights":["schema 是单一数据模型入口","生成的客户端类型提示完整","Studio 等辅助工具适合检查数据"],"logo":"/media/icons/prisma.svg"}',35) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('sqlite','SQLite','backend','开源免费',0,NULL,'sqlite 一个文件就是一个数据库，简单到可以随身带走。 嵌入式关系数据库，无需单独服务进程，事务、索引和 sql 能力完整。适合本地应用、边缘数据、测试环境与规模适中的单机服务。 嵌入式数据库 sql 单文件 事务 为桌面或移动应用保存本地数据 在测试中快速创建可丢弃数据库 用单文件数据库降低小型服务运维成本','{"id":"sqlite","name":"SQLite","tagline":"一个文件就是一个数据库，简单到可以随身带走。","description":"嵌入式关系数据库，无需单独服务进程，事务、索引和 SQL 能力完整。适合本地应用、边缘数据、测试环境与规模适中的单机服务。","categoryId":"backend","website":"https://sqlite.org","tags":["嵌入式数据库","SQL","单文件","事务"],"platforms":["Web","CLI"],"pricing":"开源免费","icon":"Sq","accent":"#003B57","featured":false,"useCases":["为桌面或移动应用保存本地数据","在测试中快速创建可丢弃数据库","用单文件数据库降低小型服务运维成本"],"highlights":["无需独立服务进程，部署简单","数据完整性和 SQL 能力经过长期验证","文件可直接备份、复制和迁移"],"logo":"/media/icons/sqlite.ico"}',36) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('redis','Redis','backend','开源免费',0,NULL,'redis 以内存速度处理缓存、队列与实时数据。 广泛使用的内存数据结构存储，支持字符串、哈希、列表、集合以及发布订阅，适合缓存、限流、会话和轻量队列等场景。 缓存 内存数据库 队列 会话 缓存热点查询降低数据库压力 实现限流计数与会话存储 用列表或流构建轻量任务队列','{"id":"redis","name":"Redis","tagline":"以内存速度处理缓存、队列与实时数据。","description":"广泛使用的内存数据结构存储，支持字符串、哈希、列表、集合以及发布订阅，适合缓存、限流、会话和轻量队列等场景。","categoryId":"backend","website":"https://redis.io","github":"https://github.com/redis/redis","install":"docker run --name redis -p 6379:6379 redis","tags":["缓存","内存数据库","队列","会话"],"platforms":["Web","CLI"],"pricing":"开源免费","icon":"Rd","accent":"#DC382D","featured":false,"useCases":["缓存热点查询降低数据库压力","实现限流计数与会话存储","用列表或流构建轻量任务队列"],"highlights":["数据结构丰富，适合多种临时状态","读写路径短，延迟表现稳定","客户端与托管服务选择广泛"],"logo":"/media/icons/redis.png"}',37) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('playwright','Playwright','devops','开源免费',0,NULL,'playwright 用真实浏览器跑可靠的端到端测试与抓取。 微软开源的浏览器自动化工具，支持 chromium、firefox 和 webkit，提供自动等待、追踪与并行能力，适合端到端测试和页面流程验证。 端到端测试 浏览器自动化 多浏览器 追踪 覆盖登录、下单等关键用户路径 在多个浏览器内核上验证界面 调试时回放失败测试的完整轨迹','{"id":"playwright","name":"Playwright","tagline":"用真实浏览器跑可靠的端到端测试与抓取。","description":"微软开源的浏览器自动化工具，支持 Chromium、Firefox 和 WebKit，提供自动等待、追踪与并行能力，适合端到端测试和页面流程验证。","categoryId":"devops","website":"https://playwright.dev","github":"https://github.com/microsoft/playwright","install":"npm init playwright@latest","tags":["端到端测试","浏览器自动化","多浏览器","追踪"],"platforms":["Web","CLI"],"pricing":"开源免费","icon":"Pw","accent":"#2EAD33","featured":false,"useCases":["覆盖登录、下单等关键用户路径","在多个浏览器内核上验证界面","调试时回放失败测试的完整轨迹"],"highlights":["自动等待降低异步测试的脆弱性","三大浏览器引擎路径统一","测试追踪与代码生成工具齐全"],"logo":"/media/icons/playwright.svg"}',38) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('vitest','Vitest','devops','开源免费',0,NULL,'vitest 沿用 vite 配置的快速单元测试运行器。 与 vite 共享配置和转换链路的测试框架，提供 jest 风格 api、监听模式与覆盖率能力，适合 react、vue 以及各类 typescript 项目。 单元测试 vite 监听模式 覆盖率 为组件和工具函数编写单元测试 在开发时持续运行相关测试 复用 vite 的别名与转换配置','{"id":"vitest","name":"Vitest","tagline":"沿用 Vite 配置的快速单元测试运行器。","description":"与 Vite 共享配置和转换链路的测试框架，提供 Jest 风格 API、监听模式与覆盖率能力，适合 React、Vue 以及各类 TypeScript 项目。","categoryId":"devops","website":"https://vitest.dev","github":"https://github.com/vitest-dev/vitest","install":"npm install -D vitest","tags":["单元测试","Vite","监听模式","覆盖率"],"platforms":["Web","CLI"],"pricing":"开源免费","icon":"Vt","accent":"#6E9F18","featured":false,"useCases":["为组件和工具函数编写单元测试","在开发时持续运行相关测试","复用 Vite 的别名与转换配置"],"highlights":["与 Vite 项目配置天然衔接","监听模式和界面反馈反馈较快","兼容常见断言与 mock 习惯"],"logo":"/media/icons/vitest.svg"}',39) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('biome','Biome','devops','开源免费',0,NULL,'biome 把格式化与 lint 合成一条快速的工具链。 面向 javascript、typescript 等语言的格式化与检查工具，用单一配置和命令处理代码风格与常见问题，适合替代多工具拼接的基础链路。 格式化 lint 工具链 typescript 在提交前统一格式与基础规则 减少格式化器和 linter 的配置冲突 为编辑器与 ci 提供同一条检查命令','{"id":"biome","name":"Biome","tagline":"把格式化与 lint 合成一条快速的工具链。","description":"面向 JavaScript、TypeScript 等语言的格式化与检查工具，用单一配置和命令处理代码风格与常见问题，适合替代多工具拼接的基础链路。","categoryId":"devops","website":"https://biomejs.dev","github":"https://github.com/biomejs/biome","install":"npm install -D @biomejs/biome","tags":["格式化","Lint","工具链","TypeScript"],"platforms":["Web","CLI"],"pricing":"开源免费","icon":"Bi","accent":"#3B82F6","featured":false,"useCases":["在提交前统一格式与基础规则","减少格式化器和 linter 的配置冲突","为编辑器与 CI 提供同一条检查命令"],"highlights":["格式化与检查共享一套配置","单一可执行文件便于集成","规则与差异输出清晰易读"],"logo":"/media/icons/biome.svg"}',40) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('vercel','Vercel','devops','免费增值',0,NULL,'vercel 从 git 仓库到线上预览，缩短前端发布路径。 面向前端与全栈框架的部署平台，连接仓库后自动构建预览环境，并提供边缘网络、函数和团队协作能力，适合快速验证和持续发布。 部署 预览环境 ci/cd 前端 为每个分支生成可分享的预览站 快速部署 next.js 全栈应用 让设计评审直接查看线上效果','{"id":"vercel","name":"Vercel","tagline":"从 Git 仓库到线上预览，缩短前端发布路径。","description":"面向前端与全栈框架的部署平台，连接仓库后自动构建预览环境，并提供边缘网络、函数和团队协作能力，适合快速验证和持续发布。","categoryId":"devops","website":"https://vercel.com","install":"npx vercel","tags":["部署","预览环境","CI/CD","前端"],"platforms":["Web"],"pricing":"免费增值","icon":"Ve","accent":"#111111","featured":false,"useCases":["为每个分支生成可分享的预览站","快速部署 Next.js 全栈应用","让设计评审直接查看线上效果"],"highlights":["仓库到部署的流程非常直接","预览 URL 适合评审和回滚","与主流前端框架的适配成熟"],"logo":"/media/icons/vercel.png"}',41) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('github-actions','GitHub Actions','devops','免费增值',0,NULL,'github actions 把测试、构建与发布写成仓库里的自动化流程。 github 提供的 ci/cd 与自动化平台，用工作流文件描述触发条件和执行步骤，适合在代码仓库旁完成测试、镜像构建、发布与定时任务。 ci/cd 自动化 github 工作流 在提交或合并请求时运行测试 构建镜像并推送到镜像仓库 定时执行数据同步或维护任务','{"id":"github-actions","name":"GitHub Actions","tagline":"把测试、构建与发布写成仓库里的自动化流程。","description":"GitHub 提供的 CI/CD 与自动化平台，用工作流文件描述触发条件和执行步骤，适合在代码仓库旁完成测试、镜像构建、发布与定时任务。","categoryId":"devops","website":"https://github.com/features/actions","tags":["CI/CD","自动化","GitHub","工作流"],"platforms":["Web"],"pricing":"免费增值","icon":"GH","accent":"#2088FF","featured":false,"useCases":["在提交或合并请求时运行测试","构建镜像并推送到镜像仓库","定时执行数据同步或维护任务"],"highlights":["工作流与代码同仓，版本清楚","社区 action 覆盖大量常见步骤","事件触发器和权限配置粒度较细"],"logo":"/media/icons/github-actions.svg"}',42) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('docker','Docker','devops','免费增值',0,NULL,'docker 用容器把运行环境与依赖一起打包。 容器化工具平台，通过镜像描述运行环境，让开发、测试与生产使用相近的依赖组合，适合服务交付、数据库本地启动和构建环境隔离。 容器 镜像 环境一致 开发 为项目提供一致的本地运行环境 用 compose 启动数据库和依赖服务 构建可复用的服务镜像','{"id":"docker","name":"Docker","tagline":"用容器把运行环境与依赖一起打包。","description":"容器化工具平台，通过镜像描述运行环境，让开发、测试与生产使用相近的依赖组合，适合服务交付、数据库本地启动和构建环境隔离。","categoryId":"devops","website":"https://www.docker.com","tags":["容器","镜像","环境一致","开发"],"platforms":["Web","CLI"],"pricing":"免费增值","icon":"Do","accent":"#2496ED","featured":false,"useCases":["为项目提供一致的本地运行环境","用 Compose 启动数据库和依赖服务","构建可复用的服务镜像"],"highlights":["镜像把运行环境变成可版本化产物","Compose 适合组合本地服务","生态和基础镜像覆盖广泛"],"logo":"/media/icons/docker.png"}',43) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('pnpm','pnpm','devops','开源免费',0,NULL,'pnpm 节省磁盘、边界清晰的包管理器。 强调内容寻址存储与严格依赖隔离的包管理器，通过硬链接减少重复安装，并能管理 monorepo 中的多个 workspace。 包管理 monorepo 依赖隔离 磁盘 管理包含多个应用和包的 monorepo 在多项目环境里减少重复依赖 通过严格依赖边界发现隐式引用','{"id":"pnpm","name":"pnpm","tagline":"节省磁盘、边界清晰的包管理器。","description":"强调内容寻址存储与严格依赖隔离的包管理器，通过硬链接减少重复安装，并能管理 monorepo 中的多个 workspace。","categoryId":"devops","website":"https://pnpm.io","github":"https://github.com/pnpm/pnpm","install":"corepack enable pnpm","tags":["包管理","Monorepo","依赖隔离","磁盘"],"platforms":["CLI"],"pricing":"开源免费","icon":"pn","accent":"#D97706","featured":false,"useCases":["管理包含多个应用和包的 monorepo","在多项目环境里减少重复依赖","通过严格依赖边界发现隐式引用"],"highlights":["内容寻址存储节省重复空间","workspace 支持适合仓库内协作","依赖声明不够明确时更容易暴露问题"],"logo":"/media/icons/pnpm.png"}',44) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('expo','Expo','mobile','免费增值',1,NULL,'expo 用 react 和 typescript 做原生移动应用。 基于 react native 的应用开发平台，提供开发服务器、原生模块与构建服务，适合希望用 web 技能快速进入 ios 与 android 的团队。 react native 跨平台 原生应用 typescript 从同一个代码库开发 ios 与 android 在真机上快速预览界面改动 接入相机、通知等常见原生能力','{"id":"expo","name":"Expo","tagline":"用 React 和 TypeScript 做原生移动应用。","description":"基于 React Native 的应用开发平台，提供开发服务器、原生模块与构建服务，适合希望用 Web 技能快速进入 iOS 与 Android 的团队。","categoryId":"mobile","website":"https://expo.dev","github":"https://github.com/expo/expo","install":"npx create-expo-app@latest","tags":["React Native","跨平台","原生应用","TypeScript"],"platforms":["Mobile","Web"],"pricing":"免费增值","icon":"Ex","accent":"#4630EB","featured":true,"useCases":["从同一个代码库开发 iOS 与 Android","在真机上快速预览界面改动","接入相机、通知等常见原生能力"],"highlights":["开发、预览与云构建流程较完整","原生模块生态覆盖面广","可使用 TypeScript 和 React 习惯"],"logo":"/media/icons/expo.png"}',45) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('flutter','Flutter','mobile','开源免费',0,NULL,'flutter 一套 dart 代码构建多端原生界面。 google 开源的跨平台 ui 工具包，使用 dart 和自绘渲染引擎构建移动、桌面与 web 界面，适合重视一致视觉和高帧率交互的产品。 dart 跨平台 自绘 ui 移动开发 开发视觉高度一致的跨平台 app 构建动画和自定义绘制较多的界面 让移动与桌面共享一套组件','{"id":"flutter","name":"Flutter","tagline":"一套 Dart 代码构建多端原生界面。","description":"Google 开源的跨平台 UI 工具包，使用 Dart 和自绘渲染引擎构建移动、桌面与 Web 界面，适合重视一致视觉和高帧率交互的产品。","categoryId":"mobile","website":"https://flutter.dev","github":"https://github.com/flutter/flutter","install":"flutter create my_app","tags":["Dart","跨平台","自绘 UI","移动开发"],"platforms":["Mobile","Web"],"pricing":"开源免费","icon":"Fl","accent":"#02569B","featured":false,"useCases":["开发视觉高度一致的跨平台 App","构建动画和自定义绘制较多的界面","让移动与桌面共享一套组件"],"highlights":["自带渲染与组件体系，视觉可控","热重载提升界面迭代速度","覆盖移动、桌面与 Web 多端目标"],"logo":"/media/icons/flutter.png"}',46) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('swiftui','SwiftUI','mobile','免费使用',0,NULL,'swiftui 用声明式 swift 语法搭建 apple 平台界面。 apple 的声明式界面框架，用状态驱动视图并直接使用系统组件、动画与无障碍能力，适合深度融入 ios、ipados 和 macos 生态的应用。开发工具可免费使用，app store 上架需另按 apple 开发者计划要求安排。 apple swift 声明式 ui 原生 开发深度使用系统能力的 ios 应用 为 apple 平台构建原生界面 利用系统控件和动效保持一致体验','{"id":"swiftui","name":"SwiftUI","tagline":"用声明式 Swift 语法搭建 Apple 平台界面。","description":"Apple 的声明式界面框架，用状态驱动视图并直接使用系统组件、动画与无障碍能力，适合深度融入 iOS、iPadOS 和 macOS 生态的应用。开发工具可免费使用，App Store 上架需另按 Apple 开发者计划要求安排。","categoryId":"mobile","website":"https://developer.apple.com/xcode/swiftui/","tags":["Apple","Swift","声明式 UI","原生"],"platforms":["Mobile"],"pricing":"免费使用","icon":"Su","accent":"#FA7343","featured":false,"useCases":["开发深度使用系统能力的 iOS 应用","为 Apple 平台构建原生界面","利用系统控件和动效保持一致体验"],"highlights":["状态变化直接驱动界面更新","能自然接入 Apple 平台系统能力","开发工具免费使用，上架计划与费用另计"],"logo":"/media/icons/swiftui.png"}',47) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('react-native','React Native','mobile','开源免费',0,NULL,'react native 以 react 组件模型编写原生移动界面。 meta 开源的跨平台移动框架，用 react 声明界面并映射到原生视图，适合已有 web 团队扩展移动端，同时保留接入原生代码的空间。 react 跨平台 原生视图 移动 复用 react 经验开发移动应用 在原生模块与 js 之间按需扩展 共享业务逻辑和接口层代码','{"id":"react-native","name":"React Native","tagline":"以 React 组件模型编写原生移动界面。","description":"Meta 开源的跨平台移动框架，用 React 声明界面并映射到原生视图，适合已有 Web 团队扩展移动端，同时保留接入原生代码的空间。","categoryId":"mobile","website":"https://reactnative.dev","github":"https://github.com/facebook/react-native","install":"npx @react-native-community/cli init MyApp","tags":["React","跨平台","原生视图","移动"],"platforms":["Mobile"],"pricing":"开源免费","icon":"RN","accent":"#61DAFB","featured":false,"useCases":["复用 React 经验开发移动应用","在原生模块与 JS 之间按需扩展","共享业务逻辑和接口层代码"],"highlights":["渲染到原生视图而非 WebView","React 组件模型便于团队迁移","可按平台编写原生扩展"],"logo":"/media/icons/react-native.ico"}',48) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('capacitor','Capacitor','mobile','开源免费',0,NULL,'capacitor 给已有 web 应用补上原生壳与设备能力。 跨平台原生运行时，把 web 构建产物装进 ios 和 android 应用，并通过插件访问相机、文件等设备能力，适合已有 web 产品快速进入应用商店。 webview 原生插件 ios android 把现有网站打包为移动应用 在 web 项目中接入相机与文件系统 用同一套前端代码覆盖双端','{"id":"capacitor","name":"Capacitor","tagline":"给已有 Web 应用补上原生壳与设备能力。","description":"跨平台原生运行时，把 Web 构建产物装进 iOS 和 Android 应用，并通过插件访问相机、文件等设备能力，适合已有 Web 产品快速进入应用商店。","categoryId":"mobile","website":"https://capacitorjs.com","github":"https://github.com/ionic-team/capacitor","install":"npm install @capacitor/core @capacitor/cli","tags":["WebView","原生插件","iOS","Android"],"platforms":["Mobile"],"pricing":"开源免费","icon":"Ca","accent":"#3488D8","featured":false,"useCases":["把现有网站打包为移动应用","在 Web 项目中接入相机与文件系统","用同一套前端代码覆盖双端"],"highlights":["沿用现有前端工程与构建流程","插件体系连接原生设备能力","对原生项目的控制权留在本地"],"logo":"/media/icons/capacitor.png"}',49) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('figma','Figma','design','免费增值',0,NULL,'figma 从线框到设计系统，多人协作的设计画布。 基于浏览器的界面设计与协作工具，覆盖设计、原型、组件库和开发交付，适合产品、设计与工程在同一份文件中同步推进。 界面设计 原型 设计系统 协作 制作产品界面与可点击原型 维护跨产品的组件和变量体系 在评审中直接留下上下文评论','{"id":"figma","name":"Figma","tagline":"从线框到设计系统，多人协作的设计画布。","description":"基于浏览器的界面设计与协作工具，覆盖设计、原型、组件库和开发交付，适合产品、设计与工程在同一份文件中同步推进。","categoryId":"design","website":"https://www.figma.com","tags":["界面设计","原型","设计系统","协作"],"platforms":["Web"],"pricing":"免费增值","icon":"Fi","accent":"#F24E1E","featured":false,"useCases":["制作产品界面与可点击原型","维护跨产品的组件和变量体系","在评审中直接留下上下文评论"],"highlights":["浏览器协作降低参与门槛","组件与变量适合沉淀设计系统","设计标注与开发交接路径成熟"],"logo":"/media/icons/figma.svg"}',50) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('penpot','Penpot','design','开源免费',0,NULL,'penpot 开源的设计与原型平台，文件掌握在自己手里。 开源的设计协作工具，用基于 web 标准的方式制作界面、原型和设计系统，支持自托管，适合关注数据自主与开放格式的团队。 开源 自托管 界面设计 原型 在自有服务器上运行设计协作平台 围绕开放格式建立设计流程 让设计文件更容易进入工程链路','{"id":"penpot","name":"Penpot","tagline":"开源的设计与原型平台，文件掌握在自己手里。","description":"开源的设计协作工具，用基于 Web 标准的方式制作界面、原型和设计系统，支持自托管，适合关注数据自主与开放格式的团队。","categoryId":"design","website":"https://penpot.app","github":"https://github.com/penpot/penpot","tags":["开源","自托管","界面设计","原型"],"platforms":["Web"],"pricing":"开源免费","icon":"Pe","accent":"#12A594","featured":false,"useCases":["在自有服务器上运行设计协作平台","围绕开放格式建立设计流程","让设计文件更容易进入工程链路"],"highlights":["开源实现支持自主部署","基于 Web 标准组织设计产物","组件、原型与协作能力齐全"],"logo":"/media/icons/penpot.ico"}',51) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('excalidraw','Excalidraw','design','开源免费',0,NULL,'excalidraw 打开就能画的虚拟白板，手绘感刚刚好。 轻量的手绘风白板工具，适合画流程图、架构草图与产品构思，支持协作和嵌入，也可以作为 react 组件加入自己的产品。 白板 流程图 手绘风 协作 画系统架构和用户流程草图 在会议中快速对齐产品方案 把白板能力嵌入团队内部工具','{"id":"excalidraw","name":"Excalidraw","tagline":"打开就能画的虚拟白板，手绘感刚刚好。","description":"轻量的手绘风白板工具，适合画流程图、架构草图与产品构思，支持协作和嵌入，也可以作为 React 组件加入自己的产品。","categoryId":"design","website":"https://excalidraw.com","github":"https://github.com/excalidraw/excalidraw","install":"npm install @excalidraw/excalidraw","tags":["白板","流程图","手绘风","协作"],"platforms":["Web"],"pricing":"开源免费","icon":"Ec","accent":"#6965DB","featured":false,"useCases":["画系统架构和用户流程草图","在会议中快速对齐产品方案","把白板能力嵌入团队内部工具"],"highlights":["手绘风格让草图不显得过度正式","无需复杂设置即可开始画","开源组件便于嵌入自有产品"],"logo":"/media/icons/excalidraw.png"}',52) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('unsplash','Unsplash','design','免费增值',0,NULL,'unsplash 为界面与内容提供高质量摄影素材。 摄影作品分享与素材平台，提供大量可检索的图片并附带使用许可说明，适合为文章、演示和视觉稿寻找更真实的图像素材。 图片素材 摄影 授权 灵感 为文章或演示寻找配图 制作情绪板和视觉参考 为早期产品原型补充真实图片','{"id":"unsplash","name":"Unsplash","tagline":"为界面与内容提供高质量摄影素材。","description":"摄影作品分享与素材平台，提供大量可检索的图片并附带使用许可说明，适合为文章、演示和视觉稿寻找更真实的图像素材。","categoryId":"design","website":"https://unsplash.com","tags":["图片素材","摄影","授权","灵感"],"platforms":["Web"],"pricing":"免费增值","icon":"Un","accent":"#111111","featured":false,"useCases":["为文章或演示寻找配图","制作情绪板和视觉参考","为早期产品原型补充真实图片"],"highlights":["图片风格和题材覆盖广泛","搜索与收藏体验直接","使用前可查看每张图片的许可说明"],"logo":"/media/icons/unsplash.ico"}',53) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('google-fonts','Google Fonts','design','开源免费',0,NULL,'google fonts 跨平台可用的开放字体资源库。 google 维护的开放字体目录，提供多语言字体与网页加载方式，适合快速比较字体气质并在项目中引入可托管的字体资源。 字体 开源 多语言 网页字体 为网站挑选并引入网页字体 比较中英文字体的组合效果 找到适合展示标题的开放字体','{"id":"google-fonts","name":"Google Fonts","tagline":"跨平台可用的开放字体资源库。","description":"Google 维护的开放字体目录，提供多语言字体与网页加载方式，适合快速比较字体气质并在项目中引入可托管的字体资源。","categoryId":"design","website":"https://fonts.google.com","github":"https://github.com/google/fonts","tags":["字体","开源","多语言","网页字体"],"platforms":["Web"],"pricing":"开源免费","icon":"Ag","accent":"#A16207","featured":false,"useCases":["为网站挑选并引入网页字体","比较中英文字体的组合效果","找到适合展示标题的开放字体"],"highlights":["字体数量与语言覆盖广","可直接获得字体文件和加载方案","每款字体的许可信息清楚可查"],"logo":"/media/icons/google-fonts.svg"}',54) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('tiptap','Tiptap','content','免费增值',1,'tiptap-json','tiptap 以 prosemirror 为底，搭出可定制的富文本编辑器。 基于 prosemirror 的无头编辑器框架，提供扩展、协作与 ui 组件生态。编辑逻辑和界面分离，适合按产品需要组装自己的编辑体验。 富文本 prosemirror 可扩展 react 搭建笔记或文档产品的编辑器 按业务添加自定义节点和命令 为编辑能力接入协作和评论','{"id":"tiptap","name":"Tiptap","tagline":"以 ProseMirror 为底，搭出可定制的富文本编辑器。","description":"基于 ProseMirror 的无头编辑器框架，提供扩展、协作与 UI 组件生态。编辑逻辑和界面分离，适合按产品需要组装自己的编辑体验。","categoryId":"content","website":"https://tiptap.dev","github":"https://github.com/ueberdosis/tiptap","install":"npm install @tiptap/react @tiptap/pm @tiptap/starter-kit","tags":["富文本","ProseMirror","可扩展","React"],"platforms":["Web"],"pricing":"免费增值","icon":"Ti","accent":"#6A5ACD","featured":true,"demoId":"tiptap-json","useCases":["搭建笔记或文档产品的编辑器","按业务添加自定义节点和命令","为编辑能力接入协作和评论"],"highlights":["无头设计让界面完全可控","基于 ProseMirror 的文档模型稳健","扩展生态覆盖常见编辑能力"],"logo":"/media/icons/tiptap.png"}',55) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('lexical','Lexical','content','开源免费',0,'lexical-history','lexical meta 开源的编辑器框架，面向扩展与性能。 以可组合节点和命令系统为核心的编辑器框架，提供 react 绑定，适合构建需要自定义内容模型、精细控制渲染和输入行为的编辑体验。 编辑器框架 react 可扩展 meta 开发具有自定义块结构的编辑器 实现受控的富文本输入体验 为评论或笔记组件加入编辑能力','{"id":"lexical","name":"Lexical","tagline":"Meta 开源的编辑器框架，面向扩展与性能。","description":"以可组合节点和命令系统为核心的编辑器框架，提供 React 绑定，适合构建需要自定义内容模型、精细控制渲染和输入行为的编辑体验。","categoryId":"content","website":"https://lexical.dev","github":"https://github.com/facebook/lexical","install":"npm install lexical @lexical/react","tags":["编辑器框架","React","可扩展","Meta"],"platforms":["Web"],"pricing":"开源免费","icon":"Le","accent":"#1D4ED8","featured":false,"demoId":"lexical-history","useCases":["开发具有自定义块结构的编辑器","实现受控的富文本输入体验","为评论或笔记组件加入编辑能力"],"highlights":["文档模型和 DOM 渲染边界清晰","命令与节点体系便于扩展","React 绑定和示例覆盖常见场景"],"logo":"/media/icons/lexical.ico"}',56) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('monaco','Monaco Editor','content','开源免费',0,NULL,'monaco editor 把 vs code 同源的代码编辑体验嵌进网页。 驱动 vs code 的代码编辑器组件，提供语法高亮、智能提示、差异视图和主题能力，适合在线代码试用、配置编辑和教育产品。 代码编辑器 语法高亮 vs code web 搭建在线代码演示或沙盒 让用户在网页中编辑配置 展示代码差异与语法提示','{"id":"monaco","name":"Monaco Editor","tagline":"把 VS Code 同源的代码编辑体验嵌进网页。","description":"驱动 VS Code 的代码编辑器组件，提供语法高亮、智能提示、差异视图和主题能力，适合在线代码试用、配置编辑和教育产品。","categoryId":"content","website":"https://microsoft.github.io/monaco-editor/","github":"https://github.com/microsoft/monaco-editor","install":"npm install monaco-editor","tags":["代码编辑器","语法高亮","VS Code","Web"],"platforms":["Web"],"pricing":"开源免费","icon":"Mc","accent":"#0078D4","featured":false,"useCases":["搭建在线代码演示或沙盒","让用户在网页中编辑配置","展示代码差异与语法提示"],"highlights":["接近桌面编辑器的输入与补全体验","语言服务可扩展自定义智能提示","主题和差异视图能力成熟"]}',57) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('markdown-it','markdown-it','content','开源免费',0,'markdown-safe','markdown-it 忠实、可扩展的 markdown 解析器。 遵循 commonmark 的 javascript markdown 解析器，插件机制清晰，可用于生成文档页面、消息渲染或编辑器的预览层，处理不可信内容时仍需自行净化。 markdown 解析器 commonmark 插件 把 markdown 内容渲染成文档页面 为评论或说明字段提供格式支持 通过插件扩展语法与输出规则','{"id":"markdown-it","name":"markdown-it","tagline":"忠实、可扩展的 Markdown 解析器。","description":"遵循 CommonMark 的 JavaScript Markdown 解析器，插件机制清晰，可用于生成文档页面、消息渲染或编辑器的预览层，处理不可信内容时仍需自行净化。","categoryId":"content","website":"https://markdown-it.github.io","github":"https://github.com/markdown-it/markdown-it","install":"npm install markdown-it","tags":["Markdown","解析器","CommonMark","插件"],"platforms":["Web"],"pricing":"开源免费","icon":"Md","accent":"#0A7EA4","featured":false,"useCases":["把 Markdown 内容渲染成文档页面","为评论或说明字段提供格式支持","通过插件扩展语法与输出规则"],"highlights":["CommonMark 兼容路径清楚","规则和插件拆分细致","可作为多个框架的解析底座"],"logo":"/media/icons/markdown-it.png","demoId":"markdown-safe"}',58) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('mdx','MDX','content','开源免费',0,NULL,'mdx 在 markdown 里写 jsx，让文档拥有组件能力。 把 markdown 与 jsx 结合的内容格式和工具链，让文档可以直接使用项目组件，适合组件库文档、教程和需要交互示例的技术内容。 mdx jsx 文档 组件库 为组件库编写带真实示例的文档 在教程中嵌入可运行组件 把文档纳入前端构建流程','{"id":"mdx","name":"MDX","tagline":"在 Markdown 里写 JSX，让文档拥有组件能力。","description":"把 Markdown 与 JSX 结合的内容格式和工具链，让文档可以直接使用项目组件，适合组件库文档、教程和需要交互示例的技术内容。","categoryId":"content","website":"https://mdxjs.com","github":"https://github.com/mdx-js/mdx","install":"npm install @mdx-js/rollup","tags":["MDX","JSX","文档","组件库"],"platforms":["Web"],"pricing":"开源免费","icon":"Mx","accent":"#B45309","featured":false,"useCases":["为组件库编写带真实示例的文档","在教程中嵌入可运行组件","把文档纳入前端构建流程"],"highlights":["Markdown 的自然表达与组件能力结合","示例可以和源码共享同一组件","与现代打包工具集成路径明确"],"logo":"/media/icons/mdx.ico"}',59) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('pandoc','Pandoc','content','开源免费',0,NULL,'pandoc 在几十种文档格式之间稳定转换。 通用的文档转换工具，支持 markdown、html、latex、docx、epub 等多种输入输出格式，适合把写作内容交给脚本批量发布或归档。 文档转换 markdown cli 自动化 把 markdown 批量导出为 word 或 pdf 在书籍与网页格式之间转换 将文档转换接入发布脚本','{"id":"pandoc","name":"Pandoc","tagline":"在几十种文档格式之间稳定转换。","description":"通用的文档转换工具，支持 Markdown、HTML、LaTeX、DOCX、EPUB 等多种输入输出格式，适合把写作内容交给脚本批量发布或归档。","categoryId":"content","website":"https://pandoc.org","github":"https://github.com/jgm/pandoc","tags":["文档转换","Markdown","CLI","自动化"],"platforms":["CLI"],"pricing":"开源免费","icon":"Pa","accent":"#6B4FBB","featured":false,"useCases":["把 Markdown 批量导出为 Word 或 PDF","在书籍与网页格式之间转换","将文档转换接入发布脚本"],"highlights":["支持的格式范围很广","命令行参数适合批处理和自动化","模板和过滤器可定制输出"],"logo":"/media/icons/pandoc.svg"}',60) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('raycast','Raycast','productivity','免费增值',0,NULL,'raycast 把常用命令、搜索与脚本收进一个快捷启动器。 macos 上的快捷启动与效率工具，用扩展连接开发服务、系统命令和个人脚本，适合减少窗口切换，让高频操作集中到一个入口。 启动器 扩展 快捷操作 macos 快速唤起常用应用与命令 通过扩展查询项目与协作工具 把重复脚本接到统一快捷键','{"id":"raycast","name":"Raycast","tagline":"把常用命令、搜索与脚本收进一个快捷启动器。","description":"macOS 上的快捷启动与效率工具，用扩展连接开发服务、系统命令和个人脚本，适合减少窗口切换，让高频操作集中到一个入口。","categoryId":"productivity","website":"https://www.raycast.com","tags":["启动器","扩展","快捷操作","macOS"],"platforms":["Web"],"pricing":"免费增值","icon":"Ra","accent":"#F04A4A","featured":false,"useCases":["快速唤起常用应用与命令","通过扩展查询项目与协作工具","把重复脚本接到统一快捷键"],"highlights":["键盘优先，操作路径短","扩展生态连接大量服务","脚本与快捷方式可逐步积累"],"logo":"/media/icons/raycast.png"}',61) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('obsidian','Obsidian','productivity','免费增值',0,NULL,'obsidian 以本地 markdown 文件组成的知识网络。 面向个人知识管理的笔记工具，文件以 markdown 保存在本地，通过双向链接、图谱和插件组织内容，适合长期积累技术笔记与想法。 笔记 markdown 本地优先 知识库 整理碎片化技术笔记与读书摘录 用双向链接建立主题索引 维护属于自己的长期知识库','{"id":"obsidian","name":"Obsidian","tagline":"以本地 Markdown 文件组成的知识网络。","description":"面向个人知识管理的笔记工具，文件以 Markdown 保存在本地，通过双向链接、图谱和插件组织内容，适合长期积累技术笔记与想法。","categoryId":"productivity","website":"https://obsidian.md","tags":["笔记","Markdown","本地优先","知识库"],"platforms":["Web"],"pricing":"免费增值","icon":"Ob","accent":"#7C3AED","featured":false,"useCases":["整理碎片化技术笔记与读书摘录","用双向链接建立主题索引","维护属于自己的长期知识库"],"highlights":["数据以本地 Markdown 文件存储","链接与图谱帮助发现内容关联","插件生态支持个性化工作流"],"logo":"/media/icons/obsidian.svg"}',62) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
