INSERT INTO tools(id,name,category_id,pricing,featured,demo_id,search_text,payload,position) VALUES('notion','Notion','productivity','免费增值',0,NULL,'notion 文档、数据库与协作空间的长连接。 把页面、数据库和协作内容组合在一个工作区中的生产力工具，适合沉淀团队文档、项目资料与轻量流程，并用模板建立自己的工作方式。 文档 数据库 协作 工作区 整理项目说明和团队知识库 搭建内容日历或轻量 crm 把文档与任务放进同一个空间','{"id":"notion","name":"Notion","tagline":"文档、数据库与协作空间的长连接。","description":"把页面、数据库和协作内容组合在一个工作区中的生产力工具，适合沉淀团队文档、项目资料与轻量流程，并用模板建立自己的工作方式。","categoryId":"productivity","website":"https://www.notion.com","tags":["文档","数据库","协作","工作区"],"platforms":["Web"],"pricing":"免费增值","icon":"No","accent":"#111111","featured":false,"useCases":["整理项目说明和团队知识库","搭建内容日历或轻量 CRM","把文档与任务放进同一个空间"],"highlights":["页面与数据库可以自由组合","模板降低重复搭建成本","多人协作与分享控制较完整"],"logo":"/media/icons/notion.ico"}',64) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category_id=excluded.category_id,pricing=excluded.pricing,featured=excluded.featured,demo_id=excluded.demo_id,search_text=excluded.search_text,payload=excluded.payload,position=excluded.position;
